/// <summary>
/// find NDXRequisitionYearParameters
/// </summary>
/// <param name = "_requisitionYear">Year</param>
/// <param name = "_requisitionMonth">Month</param>
/// <param name = "_update">for update</param>
/// <returns>NDXRequisitionYearParameters record</returns>
static NDXRequisitionYearParameters find(YearBase _requisitionYear, Months _requisitionMonth, boolean _update = false)
{
    NDXRequisitionYearParameters requisitionYearParameters;

    if (_requisitionYear)
    {
        requisitionYearParameters.selectForUpdate(_update);

        select firstonly requisitionYearParameters
            where requisitionYearParameters.RequisitionYear  == _requisitionYear
                && requisitionYearParameters.RequisitionMonth == _requisitionMonth;
    }
    return requisitionYearParameters;
}

/// <summary>
/// find or creates NDXRequisitionYearParameters
/// </summary>
/// <param name = "_requisitionYear">Year</param>
/// <param name = "_requisitionMonth">Month</param>
/// <returns>NDXRequisitionYearParameters record</returns>
static NDXRequisitionYearParameters findOrCreate(YearBase _requisitionYear, Months _requisitionMonth)
{
    NDXRequisitionYearParameters requisitionYearParameters;

    requisitionYearParameters = NDXRequisitionYearParameters::find(_requisitionYear, _requisitionMonth, true);
    if (!requisitionYearParameters)
    {
        requisitionYearParameters.RequisitionYear   = _requisitionYear;
        requisitionYearParameters.RequisitionMonth  = _requisitionMonth;
        requisitionYearParameters.insert();
    }
    return requisitionYearParameters;
}

/// <summary>
/// Calculate new ID
/// </summary>
/// <param name = "_requisitionYear">Year</param>
/// <param name = "_requisitionMonth">Month</param>
/// <returns>RequisitionId</returns>
static NDXRequisitionId getNewIdForYearMonth(YearBase _requisitionYear = year(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
                                             , Months _requisitionMonth = mthofyr(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone())))
{
    NDXRequisitionYearParameters   requisitionYearParameters;

    requisitionYearParameters = NDXRequisitionYearParameters::findOrCreate(_requisitionYear, _requisitionMonth);
    requisitionYearParameters.RequisitionMonthId += 1;

    ttsbegin;
    requisitionYearParameters.update();
    ttscommit;

    return requisitionYearParameters.getRequisitionId();
}

/// <summary>
/// Gets RequisitionId
/// </summary>
/// <returns>RequisitionId</returns>
NDXRequisitionId getRequisitionId()
{
    return strfmt('%1.%2.%3', this.RequisitionYear, StrRFix(int2str(this.RequisitionMonth) ,2,'0'), StrRFix(int2str(this.RequisitionMonthId),5,'0'));
}
